\draw[->] (-0.6,0)--(4.7,0) node[right] {$x$};
\draw[->] (0,-0.5)--(0,4.6) node[above] {$y$};
\draw[thick,gray,dashed,->,domain=0:4.4,smooth,samples=51,variable=\x] plot ({\x},{2*sqrt(\x)});
\draw[thick,blue,->,domain=0:4.4,smooth,samples=51,variable=\x] plot ({\x},{sqrt(\x)});
\node[blue,right] at (3.6,1.7) {$y=\sqrt{x}$};
\node[gray,right] at (2.6,3.6) {dashed};
\fill (4,2) circle (2pt) node[above left] {$(4,2)$};
\fill[gray] (4,4) circle (1.5pt) node[above left] {$(4,4)$};
\end{tikzpicture}
[/tikz]

